class Solution {
    public int minMovesToSeat(int[] seats,int[] students){
        Arrays.sort(seats);
        Arrays.sort(students);
        int answer=0;
        for(int i=0;i<seats.length;i++)answer+=Math.abs(seats[i]-students[i]);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun minMovesToSeat(seats:IntArray,students:IntArray):Int{
        seats.sort();
        students.sort();
        return seats.indices.sumOf{
            kotlin.math.abs(seats[it]-students[it])
        }
    }
}

code.cpp:
class Solution {
    public: int minMovesToSeat(vector<int>& seats,vector<int>& students){
        sort(seats.begin(),seats.end());
        sort(students.begin(),students.end());
        int answer=0;
        for(int i=0;i<(int)seats.size();++i)answer+=abs(seats[i]-students[i]);
        return answer;
    }
};
